// ============================================================================
//  RynthCore.Engine - ImGui/MonsterHud/CreatureSizes.cs
//  How tall each kind of creature is, for the plates that hang above its head.
//
//  The table (CreatureSizes.g.cs) is generated by tools/CreatureSizes from the ACE world database and
//  client_portal.dat: weenie class id -> model height x default scale, in centimetres. A creature that is
//  not in it (a custom weenie that was not exported, a model with no height) is unknown, and the HUD
//  falls back to its estimate by creature type and name. Pure code; tools/CreatureSizesTests compiles it in.
// ============================================================================

using System;

namespace RynthCore.Engine.ImGuiBackend.Hud;

internal static partial class CreatureSizes
{
    /// <summary>Creatures in the table.</summary>
    public static int Count => Wcids.Length;

    /// <summary>Metres from the creature's feet to the top of its model, for a weenie class id; false when the table has none.</summary>
    public static bool TryGetTop(uint wcid, out float metres)
    {
        metres = 0f;
        if (wcid > int.MaxValue) return false;
        int i = Array.BinarySearch(Wcids, (int)wcid);
        if (i < 0) return false;
        metres = TopCm[i] / 100f;
        return true;
    }
}
